function [qe] = qerr(q_ref, q)
%QERR  The error quaternion conj(q_ref) q, its sign fixed so that w >= 0.
%   q_ref: real[1][4] (passed a plain number)
%   q: real[1][4] (passed a plain number)
%   returns qe: real[1][4] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    qe = zeros(4, 1);
    qe = asils.models.math.qmult(asils.models.math.qconj(q_ref), q);
    if (qe(4) < 0)
        qe = [(-(qe(1))); (-(qe(2))); (-(qe(3))); (-(qe(4)))];
    end
end
